function sig(t) { return Math.sin(3 * Math.PI * t); }        // the message signal
function envAM(t) { return 0.55 + 0.45 * sig(t); }           // AM envelope
function fmPhase(t) { return 2 * Math.PI * 16 * t - 4 * Math.cos(3 * Math.PI * t); }
function fmFreq(t) { return 16 + 6 * sig(t); }               // instantaneous cycles

var Y_SIG = 90, A_SIG = 45;
var Y_AM = 270, A_AM = 70;
var Y_FM = 480, A_FM = 60;

var state = { t: 0.15, decode: 'AM' };

function samplePath(fn, n) {
  var d = '';
  for (var i = 0; i <= n; i++) {
    var t = i / n, p = fn(t);
    d += (i === 0 ? 'M' : 'L') + p[0].toFixed(1) + ' ' + p[1].toFixed(1);
  }
  return d;
}

