// @FIGURE_CODE_BEGIN
var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
var W = 800, H = 620;
draw.viewbox(0, 0, W, H);

var X0 = 20, XW = 690;                 // traces span x in [20, 710]
function sx(t) { return X0 + t * XW; }
function sig(t) { return Math.sin(3 * Math.PI * t); }              // message: 1.5 periods
function envAM(t) { return 0.7 + 0.3 * sig(t); }                   // moderate modulation depth
function fmPhase(t) { return 2 * Math.PI * 15 * t - 3.4 * Math.cos(3 * Math.PI * t); }
function fmFreq(t) { return 15 + 5.1 * sig(t); }                   // instantaneous cycles

var Y_SIG = 78, A_SIG = 42;
var Y_AM = 275, A_AM = 74;
var Y_FM = 492, A_FM = 64;

var state = { t: 0.15, decode: 'AM', showDecoded: false };

function samplePath(fn, n) {
  var d = '';
  for (var i = 0; i <= n; i++) {
    var t = i / n, p = fn(t);
    d += (i === 0 ? 'M' : 'L') + p[0].toFixed(1) + ' ' + p[1].toFixed(1);
  }
  return d;
}

// ── Signal trace (black, ~1.5 periods) ─────────────────────────────────────
var sigTrace = draw.path(samplePath(function (t) { return [sx(t), Y_SIG - A_SIG * sig(t)]; }, 200))
  .fill('none').stroke({ color: '#222', width: 3.5, linecap: 'round' });

// ── AM trace (brick red, uniform spacing, modulated envelope) ──────────────
var amTrace = draw.path(samplePath(function (t) {
  return [sx(t), Y_AM - A_AM * envAM(t) * Math.sin(2 * Math.PI * 18 * t)];
}, 1400)).fill('none').stroke({ color: '#c0392b', width: 3, linecap: 'round' });

// ── FM trace (medium blue, constant amplitude, modulated spacing) ──────────
var fmTrace = draw.path(samplePath(function (t) {
  return [sx(t), Y_FM - A_FM * Math.sin(fmPhase(t))];
}, 1600)).fill('none').stroke({ color: '#3f5fa6', width: 3, linecap: 'round' });

// ── Row labels, right-anchored INSIDE the viewbox (never clipped) ──────────
function rowLabel(txt, y) {
  draw.text(txt).font({ size: 19, family: 'sans-serif' }).fill('#333')
    .attr({ 'text-anchor': 'end' }).move(792, y - 10);
}
rowLabel('Signal', Y_SIG - 28);
rowLabel('AM', Y_AM + 6);
rowLabel('FM', Y_FM + 6);

// ── Decoded (reconstructed) signal — hidden until decode is engaged ────────
var decodeG = draw.group().attr('opacity', 0);
var decodePath = decodeG.path('').fill('none')
  .stroke({ color: '#222', width: 3, linecap: 'round' });
var decodeLabel = decodeG.text('decoded signal').font({ size: 13, family: 'sans-serif' })
  .fill('#222').attr({ 'text-anchor': 'end', 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': 3 });

// ── Time-scan marker ────────────────────────────────────────────────────────
var markerG = draw.group();
var markerLine = markerG.line(0, 24, 0, 590)
  .stroke({ color: '#999', width: 1.5, dasharray: '6,5' });
var readoutG = markerG.group();
var readoutBg = readoutG.rect(150, 62).fill('rgba(255,255,255,0.92)').stroke({ color: '#ccc', width: 1 }).radius(4);
var readoutTxt = readoutG.text('').font({ size: 12, family: 'sans-serif' }).fill('#222');
var markerDotS = markerG.circle(7).fill('#222');
var markerDotA = markerG.circle(7).fill('#c0392b');
var markerDotF = markerG.circle(7).fill('#3f5fa6');

function explain(el, tip, title, body) {
  el.css('cursor', 'pointer');
  el.on('mousemove', function (e) { showTooltip(tip, e); })
    .on('mouseleave', function () { hideTooltip(); })
    .on('click', function () { showPopup(title, body); });
}
explain(sigTrace, 'The message to transmit', 'Signal',
  'This slow wave is the information itself — a voice, a note. It is far too slow to radiate directly, so it is imprinted onto a fast carrier.');
explain(amTrace, 'AM: peak height follows the signal', 'Amplitude Modulation',
  'The carrier cycles at a steady rate, but its amplitude (peak height) is scaled by the signal. The envelope traced by the peaks is the message.');
explain(fmTrace, 'FM: cycle spacing follows the signal', 'Frequency Modulation',
  'The carrier keeps a constant amplitude, but its instantaneous frequency rises and falls with the signal. Cycles bunch under crests and stretch under troughs.');

// ── Update logic ────────────────────────────────────────────────────────────
function updateMarker() {
  var t = state.t, x = sx(t);
  markerLine.plot(x, 24, x, 590);
  markerDotS.center(x, Y_SIG - A_SIG * sig(t));
  markerDotA.center(x, Y_AM - A_AM * envAM(t) * Math.sin(2 * Math.PI * 18 * t));
  markerDotF.center(x, Y_FM - A_FM * Math.sin(fmPhase(t)));
  readoutTxt.clear();
  readoutTxt.tspan('signal: ' + sig(t).toFixed(2)).newLine();
  readoutTxt.tspan('AM height: ' + envAM(t).toFixed(2)).newLine();
  readoutTxt.tspan('FM spacing: ' + (1 / fmFreq(t)).toFixed(3));
  var bx = (x + 10 + 160 > X0 + XW) ? x - 162 : x + 10;
  readoutBg.move(bx, 132);
  readoutTxt.move(bx + 8, 138);
}

function updateDecode() {
  var show = state.showDecoded, fm = state.decode === 'FM';
  // With no decode engaged both carriers render at full opacity (source look).
  amTrace.attr('opacity', (show && fm) ? 0.28 : 1);
  fmTrace.attr('opacity', (show && !fm) ? 0.28 : 1);
  decodeG.attr('opacity', show ? 1 : 0);
  if (show) {
    // Own clear band: just above the active carrier, well away from other curves.
    var baseY = fm ? Y_FM - 118 : Y_AM - 122;
    decodePath.plot(samplePath(function (t) { return [sx(t), baseY - A_SIG * sig(t)]; }, 200));
    decodeLabel.move(X0 + XW - 4, baseY - 30);
  }
}

function update_timeScan(v) { state.t = v; updateMarker(); }
function toggle_decodeCarrier(v, engage) {
  state.decode = v;
  if (engage) state.showDecoded = true;
  updateDecode();
}

// ── Demo step player ────────────────────────────────────────────────────────
var steps = [
  { title: 'Read the three traces', narration: 'The slow black signal sits above two fast carriers. In the red AM trace, peak heights swell and shrink; in the blue FM trace, the height stays fixed but cycles bunch and stretch.', state: { timeScan: 0.15, decodeCarrier: 'AM' }, decoded: false },
  { title: 'Scan across time', narration: 'Drag the time marker: under a signal crest the AM envelope is tall and the FM cycles are tight; under the trough the AM envelope shrinks while FM cycles spread apart.', state: { timeScan: 0.5, decodeCarrier: 'AM' }, decoded: false },
  { title: 'Decode AM', narration: 'With AM selected, the envelope traced by the red peaks is extracted and redrawn as a black curve — it matches the original signal exactly.', state: { timeScan: 0.5, decodeCarrier: 'AM' }, decoded: true },
  { title: 'Decode FM', narration: 'Switch to FM: now cycle spacing is measured instead of height, yet the reconstructed black curve is the very same signal — different property, same information.', state: { timeScan: 0.5, decodeCarrier: 'FM' }, decoded: true }
];
var stepIdx = 0;
function applyStep(i) {
  stepIdx = Math.max(0, Math.min(steps.length - 1, i));
  var s = steps[stepIdx];
  document.getElementById('demoNarration').textContent = s.narration;
  document.getElementById('stepLabel').textContent = (stepIdx + 1) + ' / ' + steps.length;
  var si = document.getElementById('timeScanInput');
  si.value = s.state.timeScan;
  document.getElementById('timeScanVal').value = s.state.timeScan;
  update_timeScan(s.state.timeScan);
  document.getElementById('decodeCarrierInput').value = s.state.decodeCarrier;
  state.showDecoded = s.decoded;
  toggle_decodeCarrier(s.state.decodeCarrier, false);
}
function nextStep() { applyStep(stepIdx + 1); }
function prevStep() { applyStep(stepIdx - 1); }

applyStep(0);
window.__markRendered();
// @FIGURE_CODE_END

