function envAM(t) { return 0.7 + 0.3 * sig(t); }                   // moderate modulation depth
function fmPhase(t) { return 2 * Math.PI * 15 * t - 3.4 * Math.cos(3 * Math.PI * t); }
function fmFreq(t) { return 15 + 5.1 * sig(t); }                   // instantaneous cycles

